# Trying one more hypothesis - maybe it's simpler
# What if the answer is just zeros where there were duplicate values in that COLUMN?

def col_duplicate_transform(grid):
    result = []
    for j in range(len(grid[0])):  # For each column
        # Count occurrences in this column
        counts = {}
        for i in range(len(grid)):
            val = grid[i][j]
            counts[val] = counts.get(val, 0) + 1
        # Build new column
        new_col = []
        for i in range(len(grid)):
            val = grid[i][j]
            if counts[val] > 1:
                new_col.append(0)
            else:
                new_col.append(val)
        result.append(new_col)
    return result

answer = col_duplicate_transform([[1, 2, 5], [7, 3, 6], [7, 6, 5]])
